 const pages=Math.max(1,Math.ceil(rows.length/pageSize)),visibleRows=rows.slice((Math.min(page,pages)-1)*pageSize,Math.min(page,pages)*pageSize),pageNumbers=[...new Set([1,page-1,page,page+1,pages].filter(number=>number>=1&&number<=pages))].sort((a,b)=>a-b);
