function CategoryModalRoute({id}){const navigate=useNavigate(),r=useRemote('/admin/categories');if(id&&!r.data)return <div className="loading">{r.error||'Se pregătește categoria…'}</div>;const record=id?r.data?.find(category=>Number(category.id)===Number(id)):{};if(id&&!record)return <Empty title="Categoria nu a fost găsită." link="/admin/categorii" label="Înapoi la categorii"/>;return <CategoryCatalog initialRecord={record} onEditorClose={()=>navigate('/admin/categorii',{replace:true})}/>;}
