function DeleteConfirm({record,close,action,archive=false,permanent=false,subject='înregistrare'}){
 const s=useStore(),[busy,setBusy]=useState(false),title=record?.name||record?.title||record?.code,product=subject==='produs',article=subject==='articol',category=subject==='categorie',coupon=subject==='cupon',definite=product?'produsul':article?'articolul':category?'categoria':coupon?'cuponul':'înregistrarea';
 const headline=archive?'Arhivezi acest produs?':permanent?'Ștergi definitiv '+definite+'?':category?'Ștergi această categorie?':'Confirmi ștergerea?',copy=archive?'Îl poți găsi oricând în lista produselor arhivate.':permanent?(product?'Produsul va fi eliminat complet din catalog, iar catalogul Stripe va fi actualizat înainte de ștergere.':coupon?'Cuponul va fi eliminat definitiv din catalog și nu va mai putea fi folosit la checkout.':'Articolul va fi eliminat complet și nu va mai apărea nici în blog, nici în administrare.'):category?'Categoria va fi eliminată dacă nu conține produse sau subcategorii.':'Această acțiune va actualiza imediat lista.';
 return <Dialog open={!!record} onClose={()=>!busy&&close()} className="admin-confirm admin-confirm-premium" label="Confirmare" motion><span className="admin-confirm-symbol">{archive?<Archive/>:<Trash2/>}</span><span className="eyebrow">{archive?'PĂSTRĂM ÎN ARHIVĂ':'ACȚIUNE DEFINITIVĂ'}</span><h2>{headline}</h2><p className="admin-confirm-record">{title}</p><p className="admin-confirm-copy">{copy}</p><div className="editor-footer"><button className="admin-button" title="Închide confirmarea fără a modifica înregistrarea" disabled={busy} onClick={close}>Renunță</button><button className="admin-button danger-button" title={archive?"Mută produsul în arhivă":"Confirmă ștergerea înregistrării"} disabled={busy} onClick={async()=>{setBusy(true);try{await action();close();s.notify(archive?'Produsul a fost arhivat.':permanent?(product?'Produsul a fost șters definitiv.':coupon?'Cuponul a fost șters definitiv.':'Articolul a fost șters definitiv.'):category?'Categoria a fost ștearsă.':'Operația a fost efectuată.');}catch(e){s.notify(e.message,'error');}finally{setBusy(false);}}}>{busy?'Se procesează…':archive?'Arhivează':permanent?'Șterge definitiv':'Confirmă'}</button></div></Dialog>;
}
