   {data&&<div className="newsletter-admin-pagination"><span>{data.total} {data.total===1?'abonat găsit':'abonați găsiți'} · pagina {data.page} din {data.pages}</span><div><button disabled={data.page<=1} onClick={()=>setPage(page-1)}><ChevronLeft/>Anterior</button>{Array.from({length:data.pages},(_,index)=>index+1).filter(number=>Math.abs(number-data.page)<=1||number===1||number===data.pages).map((number,index,array)=><React.Fragment key={number}>{index>0&&number-array[index-1]>1&&<i>…</i>}<button className={number===data.page?'active':''} onClick={()=>setPage(number)}>{number}</button></React.Fragment>)}<button disabled={data.page>=data.pages} onClick={()=>setPage(page+1)}>Următor<ChevronRight/></button></div></div>}
